function view_listing(array $__vars): void { extract($__vars, EXTR_SKIP); ?><?php
$params = array_filter(['q' => $search ?: null, 'game' => $f['game'] ?? null, 'section' => $f['section'] ?? null, 'set' => $f['set'] ?? null, 'lang' => $f['lang'] ?? null,
  'rarity' => $f['rarity'] ?? null, 'stock' => $f['stock'] ? 1 : null, 'min' => $f['min'] ?: null, 'max' => $f['max'] ?: null,
  'sort' => isset($_GET['sort']) ? $sort : null, 'per' => isset($_GET['per']) ? $per : null], fn($v) => $v !== null);
$title = $c ? ($c['h1'] ?: $c['title']) : ($search !== '' ? 'Results for â€œ' . $search . 'â€' : 'Search');
$labels = ['game' => 'Game', 'section' => 'Category', 'lang' => 'Language', 'set' => 'Set', 'rarity' => 'Rarity'];
$active = [];
foreach ($labels as $k => $lab) foreach ((array)($f[$k] ?? []) as $v) $active[] = [$v, listing_url($base, $params, [$k => array_values(array_diff((array)$f[$k], [$v])), 'page' => null])];
if ($f['stock']) $active[] = ['In stock only', listing_url($base, $params, ['stock' => null, 'page' => null])];
if ($f['min'] !== '' || $f['max'] !== '') $active[] = ['Price ' . ($f['min'] ?: '0') . 'â€“' . ($f['max'] ?: 'âˆž'), listing_url($base, $params, ['min' => null, 'max' => null, 'page' => null])];
?>
<div class="wrap">
  <nav class="crumbs" aria-label="Breadcrumb"><?php foreach ($crumbs as $i => [$t, $u]): ?><?= $i ? '<span aria-hidden="true">/</span>' : '' ?><?php if ($u && $i < count($crumbs) - 1): ?><a href="<?= h($u) ?>"><?= h($t) ?></a><?php else: ?><span><?= h($t) ?></span><?php endif ?><?php endforeach ?></nav>
  <header class="list-head">
    <div>
