        <div class="fgroup">
          <label class="switch"><input type="checkbox" name="stock" value="1" <?= $f['stock'] ? 'checked' : '' ?>><span>In stock only</span><span class="count mono"><?= number_format($instock) ?></span></label>
        </div>
        <?php foreach (['game', 'section', 'lang', 'set', 'rarity'] as $k): if (empty($facets[$k])) continue; $many = count($facets[$k]) > 8; ?>
        <fieldset class="fgroup">
          <legend class="eyebrow gold"><?= $labels[$k] ?></legend>
          <?php if ($many): ?><input class="fsearch" type="search" placeholder="Filter <?= strtolower($labels[$k]) ?>s" aria-label="Filter <?= strtolower($labels[$k]) ?> list" data-fsearch><?php endif ?>
          <div class="fopts<?= $many ? ' fopts-scroll' : '' ?>">
          <?php foreach ($facets[$k] as $r): $on = in_array($r['v'], (array)($f[$k] ?? []), true); ?>
            <label class="check"><input type="checkbox" name="<?= $k ?>[]" value="<?= h($r['v']) ?>" <?= $on ? 'checked' : '' ?>><span><?= h($r['v']) ?></span><span class="count mono"><?= number_format((int)$r['n']) ?></span></label>
          <?php endforeach ?>
          </div>
        </fieldset>
        <?php endforeach ?>
        <fieldset class="fgroup">
          <legend class="eyebrow gold">Price (<?= h(currency()) ?>)</legend>
          <div class="range"><input type="number" name="min" placeholder="Min" value="<?= h($f['min']) ?>" aria-label="Minimum price" min="0"><span>â€“</span><input type="number" name="max" placeholder="Max" value="<?= h($f['max']) ?>" aria-label="Maximum price" min="0"></div>
