function view_order(array $__vars): void { extract($__vars, EXTR_SKIP); ?><?php
$status = ['awaiting_payment' => 'Awaiting payment', 'paid' => 'Paid Â· preparing dispatch', 'shipped' => 'Shipped', 'cancelled' => 'Cancelled'][$o['status']] ?? $o['status'];
$btc = setting('btc_address');
?>
<div class="wrap narrow-wide">
  <div class="eyebrow gold">ORDER <?= h($o['code']) ?></div>
  <h1 class="h1">Thank you, <?= h(explode(' ', $o['name'])[0]) ?>.</h1>
  <p class="lead">Status: <strong><?= h($status) ?></strong>. Your stock is held until <span class="mono"><?= h(date('j M Y, H:i', strtotime($o['hold_until']))) ?> UTC</span>. A copy of this order was sent to <?= h($o['email']) ?>.</p>

  <div class="split">
    <section class="panel-box">
      <h2 class="h3">Payment</h2>
      <?php if ($o['status'] !== 'awaiting_payment'): ?>
        <p>Payment received. <?= $o['tracking'] ? 'Tracking: <span class="mono">' . h($o['tracking']) . '</span>' : '' ?></p>
      <?php elseif ($o['payment_method'] === 'bitcoin' && $btc): $uri = 'bitcoin:' . $btc . ($o['btc_amount'] ? '?amount=' . $o['btc_amount'] : ''); $held = strtotime($o['created_at']) + 3600; ?>
        <div class="btc-pay" data-btc data-usd="<?= h((string)$o['total_usd']) ?>" data-addr="<?= h($btc) ?>" data-amount="<?= h((string)$o['btc_amount']) ?>">
          <div class="btc-qr" data-qr="<?= h($uri) ?>" aria-label="QR code for the Bitcoin payment"></div>
          <div>
            <p>Send exactly</p>
            <p class="big mono" data-btc-amount><?= $o['btc_amount'] ? h($o['btc_amount']) . ' BTC' : 'Working out the BTC amountâ€¦' ?></p>
            <p class="small muted">= <?= money((float)$o['total_usd'], 'USD', true) ?><?= $o['btc_rate'] ? ' at ' . money((float)$o['btc_rate'], 'USD') . ' per BTC' : '' ?>. <?= time() < $held ? 'This amount is held for 60 minutes, until ' . date('H:i', $held) . ' UTC.' : 'If more than 60 minutes have passed, reply to your order email and we will confirm the amount.' ?></p>
            <p class="small">To this address:</p>
            <p class="mono btc" data-copy><?= h($btc) ?></p>
            <div class="btns"><button class="btn btn-sm" type="button" data-copy-btn>Copy address</button><a class="btn btn-sm" href="<?= h($uri) ?>">Open in wallet</a></div>
          </div>
        </div>
        <p class="small muted">We email your receipt once the payment confirms on the network, usually 10â€“60 minutes, and ship within 48 hours. Check that this address matches the one on our <a href="/payment-methods">payment methods</a> page. We never send a different Bitcoin address by email or chat.</p>
      <?php else: $pm = PAYMENT_METHODS[$o['payment_method']] ?? PAYMENT_METHODS['other']; ?>
