      <tr><td colspan="3">Shipping<?= $o['weight_kg'] ? ' <span class="muted small">(' . number_format((float)$o['weight_kg'], 1) . ' kg)</span>' : '' ?></td><td class="num mono"><?= $o['shipping_usd'] === null ? 'On invoice' : ((float)$o['shipping_usd'] == 0 ? 'Free' : money((float)$o['shipping_usd'], 'USD')) ?></td></tr>
