.btn[disabled]{opacity:.5;cursor:not-allowed}
label{display:flex;flex-direction:column;gap:6px;font-size:14px;font-weight:500;margin-bottom:14px}
label.inline{flex-direction:row;align-items:center;gap:8px;font-weight:400;margin-bottom:8px}
